{
  window.authorityRecords.push({
    region: 'Northern edge', from: '1635-01-15', until: '1676-07-10', status: 'claim',
    name: 'Seigneurie de La Citière (La Citiere)',
    detail: 'The Compagnie de la Nouvelle-France granted François de Lauzon a fief on 15 January 1635, French Gregorian calendar. The calls extend south toward the sea between parallels from two St Lawrence landmarks. The archive editor identified the Saint-François mouth and an extent reaching Lake Champlain. The relation of these calls to the illustrated sheet is uncertain. Montmagny delivered possession to Nicolas Trevet for Lauzon on 29 July 1638. A 10 July 1676 act records that the fief had reverted to the Crown by then. The precise reversion date is unknown. Archives de Québec, Inventaire des concessions en fief et seigneurie, vol. I, pp. 48–50.',
    url: 'https://www.patrimoinequebec.ca/Archive/BIBLIOTHEQUE/18-inventairedesconcessions1.pdf'
  });
}

