window.authorityRecords.push({
  region:'New Hampshire', from:'1673-10', until:null, status:'claim', point:[4942,2570],
  name:'Old Dunstable plantation grant (Dunstable, Nashua)',
  detail:'The Massachusetts General Court granted the petition of Thomas Brattle, James Parker, Jonathan Tyng, William Lakin and associates. The petition bounded the tract by Chelmsford, Groton, Brenton’s farm, the Souhegan farms and Henry Kimball’s farm across the Merrimack. The roughly 14,000 acres stated refer to farms already held inside the proposed plantation. The court reserved 500 acres for public use and required settlement within three years and support for a minister. Published accounts differ by a day on the October order. The point uses the existing Dunstable locality and represents only the southern part of a tract across the later state boundary. Massachusetts Archives 112, p. 232, transcribed in New Hampshire State Papers XXIV, pp. 83–84.',
  url:'https://www.pelhamnhhistory.org/library/pdffiles/statepapers/NHSP-V24.pdf'
});

